package main

// fold_tags.go — the tag parser for HTML/XML. It reads the tags
// themselves (<tag> opens, </tag> closes and is not shown, <tag/> is
// a leaf, <!-- --> and <![CDATA[ ... ]]> are skipped, declarations
// are leaves, HTML void elements never close), so it nests correctly
// regardless of indentation — unlike the indent parser, which trusts
// the source's layout. Generated by Gemini from a prompt Hana wrote
// (see gemini-test/tag_parser_prompt.txt), then fixed by Hana for two
// bugs the comparison found: a comment with code after it on the same
// line keeps the code, and a multi-line void element tracks its
// attributes until its '>' arrives. Comparison and fixes:
// testdb/tag-comparison/COMPARISON.md.

import (
	"strings"
	"unicode"
)

type tagFrame struct {
	name string
	node *Node
}

var htmlVoidElements = map[string]bool{
	"area":   true,
	"base":   true,
	"br":     true,
	"col":    true,
	"embed":  true,
	"hr":     true,
	"img":    true,
	"input":  true,
	"link":   true,
	"meta":   true,
	"source": true,
	"track":  true,
	"wbr":    true,
}

// parseTags parses HTML/XML lines into a hierarchical outline and reports whether tags are unbalanced.
func parseTags(lines []string) ([]*Node, bool) {
	var roots []*Node
	var stack []*tagFrame
	unbalanced := false

	inComment := false        // Rule 5: tracks multi-line <!-- --> comments
	inCDATA := false          // Rule 10: tracks multi-line <![CDATA[ ... ]]> sections
	pendingTagClose := false  // Rule 8: true while a multi-line opening tag has not yet seen '>'
	pendingSelfClose := false // Rule 3 & 8: true if a multi-line opening tag ends with '/>'

	addNode := func(n *Node) {
		if len(stack) > 0 {
			parent := stack[len(stack)-1].node
			parent.Children = append(parent.Children, n)
			return
		}
		roots = append(roots, n)
	}

	for i, raw := range lines {
		lineNum := i + 1
		trimmed := strings.TrimSpace(raw)

		if inComment {
			// Rule 5: skip content lines inside a multi-line comment until '-->'.
			if strings.Contains(trimmed, "-->") {
				inComment = false
			}
			continue
		}

		if inCDATA {
			// Rule 10: skip content lines inside a multi-line CDATA section until ']]>'.
			if strings.Contains(trimmed, "]]>") {
				inCDATA = false
			}
			continue
		}

		if pendingTagClose {
			// Rule 8: attribute lines of a multi-line opening tag nest under the tag node.
			hasClose := strings.Contains(trimmed, ">")
			if strings.HasSuffix(trimmed, "/>") {
				pendingSelfClose = true
			}
			if hasClose {
				pendingTagClose = false
				if pendingSelfClose && len(stack) > 0 {
					// Rule 3: self-closing tag is a leaf, not an open container.
					stack = stack[:len(stack)-1]
				}
				pendingSelfClose = false
				continue
			}
			addNode(&Node{Line: lineNum, Text: cleanText(raw)})
			continue
		}

		if strings.HasPrefix(trimmed, "<!--") {
			// Rule 5: skip single-line or starting multi-line comments.
			// A comment with code after it on the same line keeps the code:
			// only the part after the first "-->" is processed below.
			if idx := strings.Index(trimmed, "-->"); idx >= 0 {
				trimmed = strings.TrimSpace(trimmed[idx+3:])
				if trimmed == "" {
					continue
				}
			} else {
				inComment = true
				continue
			}
		}

		if strings.HasPrefix(trimmed, "<![CDATA[") {
			// Rule 10: skip single-line or starting multi-line CDATA sections.
			if !strings.Contains(trimmed[9:], "]]>") {
				inCDATA = true
			}
			continue
		}

		if !strings.Contains(trimmed, "<") {
			// Rule 9: plain text-only lines are skipped.
			continue
		}

		if isDeclaration(trimmed) {
			// Rule 6: XML/DOCTYPE declarations are leaves.
			addNode(&Node{Line: lineNum, Text: cleanText(raw)})
			continue
		}

		if strings.HasPrefix(trimmed, "</") {
			// Rule 2 & Rule 11 & Rule 12: process closing tag(s) without adding nodes.
			closers := extractClosingTags(trimmed)
			for _, tag := range closers {
				if len(stack) > 0 && stack[len(stack)-1].name == tag {
					stack = stack[:len(stack)-1]
				} else {
					unbalanced = true
				}
			}
			continue
		}

		openName, hasOpenTag := extractOpeningTagName(trimmed)
		if !hasOpenTag {
			// Rule 9: lines without a valid tag opener are skipped.
			continue
		}

		lowerOpen := strings.ToLower(openName)
		node := &Node{Line: lineNum, Text: cleanText(raw)}

		// A void element is a leaf only when its '>' is on this line.
		// A multi-line void element (no '>' yet) is tracked like any
		// multi-line opening tag and popped when its '>' arrives, because
		// void elements are self-closing by nature.
		hasClose := strings.Contains(trimmed, ">")
		if hasClose && closesOnSameLine(trimmed, lowerOpen) {
			// Rule 3 & Rule 4 & Rule 7: self-closing, single-line open/close, or HTML void element is a leaf.
			addNode(node)
			continue
		}

		// Rule 1 & Rule 8: opening tag starts a block; if '>' is missing, attributes nest until '>'.
		addNode(node)
		stack = append(stack, &tagFrame{name: lowerOpen, node: node})
		if !hasClose {
			pendingTagClose = true
			pendingSelfClose = htmlVoidElements[lowerOpen]
		}
	}

	if len(stack) > 0 || pendingTagClose || inComment || inCDATA {
		// Unclosed tags or blocks at end of file mark the outline unbalanced.
		unbalanced = true
	}

	return roots, unbalanced
}

func isDeclaration(s string) bool {
	if strings.HasPrefix(s, "<?") {
		return true
	}
	if len(s) >= 9 && strings.EqualFold(s[:9], "<!doctype") {
		return true
	}
	return false
}

func extractOpeningTagName(s string) (string, bool) {
	idx := strings.IndexByte(s, '<')
	if idx < 0 || idx+1 >= len(s) {
		return "", false
	}
	rest := s[idx+1:]
	if strings.HasPrefix(rest, "/") || strings.HasPrefix(rest, "!") || strings.HasPrefix(rest, "?") {
		return "", false
	}
	var b strings.Builder
	for i := 0; i < len(rest); i++ {
		ch := rune(rest[i])
		if unicode.IsLetter(ch) || unicode.IsDigit(ch) || ch == '-' || ch == '_' || ch == ':' {
			b.WriteRune(ch)
		} else {
			break
		}
	}
	if b.Len() == 0 {
		return "", false
	}
	return b.String(), true
}

func closesOnSameLine(s, lowerOpen string) bool {
	if htmlVoidElements[lowerOpen] {
		return true
	}
	if strings.Contains(s, "/>") {
		return true
	}
	closers := extractClosingTags(s)
	for _, c := range closers {
		if c == lowerOpen {
			return true
		}
	}
	return false
}

func extractClosingTags(s string) []string {
	var tags []string
	start := 0
	for {
		idx := strings.Index(s[start:], "</")
		if idx < 0 {
			break
		}
		pos := start + idx + 2
		var b strings.Builder
		for i := pos; i < len(s); i++ {
			ch := rune(s[i])
			if unicode.IsLetter(ch) || unicode.IsDigit(ch) || ch == '-' || ch == '_' || ch == ':' {
				b.WriteRune(unicode.ToLower(ch))
			} else {
				break
			}
		}
		if b.Len() > 0 {
			tags = append(tags, b.String())
		}
		start = pos + b.Len()
	}
	return tags
}
